// src/app/layout.tsx
import type { Metadata, Viewport } from "next";
import { Plus_Jakarta_Sans } from "next/font/google";
import { GoogleAnalytics } from "@next/third-parties/google";
import Script from "next/script";
import { GoogleOAuthProvider } from "@react-oauth/google";
import Header from "@/components/header/header";
import Footer from "@/components/footer/footer";
import "./globals.scss";
// FontAwesome: load its CSS once and stop the runtime CSS injection so
// server-rendered icons get the correct `width: 1em` sizing.
import { config as fontAwesomeConfig } from "@fortawesome/fontawesome-svg-core";
import "@fortawesome/fontawesome-svg-core/styles.css";
fontAwesomeConfig.autoAddCss = false;
import SessionProviderWrapper from "@/components/layout/SessionProviderWrapper";
import { WishlistProvider } from "@/components/wishlist/wishlist-context";
import AffiliateTracker from "@/components/affiliate/AffiliateTracker";

const jakarta = Plus_Jakarta_Sans({
  subsets: ["latin"],
  weight: ["500", "600", "700", "800"],
  display: "swap",
  variable: "--font-jakarta",
});

export const metadata: Metadata = {
  title: "TravelShop Booking",
  description:
    "Discover unique guided tours and cultural experiences across Turkey and the world with TravelShop Booking - your trusted global travel partner.",
};

export const viewport: Viewport = {
  themeColor: "#854ec9",
};

// Tarayıcı çevirisi / DOM'a müdahale eden uzantılar yüzünden oluşan
// "NotFoundError: not a child of this node" hatalarını yakalar.
// Sağlıklı durumda davranış değişmez.
const translateCrashGuard = `(function () {
  if (typeof Node !== "function" || !Node.prototype) return;
  var warn = /^(localhost|127\\.0\\.0\\.1)$/.test(location.hostname)
    ? function (m, a, b) { try { console.warn("[translate-guard] " + m, a, b); } catch (e) {} }
    : function () {};
  var originalRemoveChild = Node.prototype.removeChild;
  Node.prototype.removeChild = function (child) {
    if (child && child.parentNode !== this) {
      warn("removeChild: node is not a child of this parent", child, this);
      return child;
    }
    return originalRemoveChild.apply(this, arguments);
  };
  var originalInsertBefore = Node.prototype.insertBefore;
  Node.prototype.insertBefore = function (newNode, referenceNode) {
    if (referenceNode && referenceNode.parentNode !== this) {
      warn("insertBefore: reference node is not a child of this parent", referenceNode, this);
      return newNode;
    }
    return originalInsertBefore.apply(this, arguments);
  };
})();`;

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" translate="no" suppressHydrationWarning>
      <head>
        {/* <script
          id="translate-crash-guard"
          dangerouslySetInnerHTML={{ __html: translateCrashGuard }}
        /> */}
      </head>
      <body className={`bg-white ${jakarta.variable}`}>
        {process.env.SERVER === "production" && (
          <Script id="yandex-metrica" strategy="lazyOnload">
            {`(function(m,e,t,r,i,k,a){m[i]=m[i]||function(){(m[i].a=m[i].a||[]).push(arguments)};
              m[i].l=1*new Date();
              for (var j = 0; j < document.scripts.length; j++) {if (document.scripts[j].src === r) { return; }}
              k=e.createElement(t),a=e.getElementsByTagName(t)[0],k.async=1,k.src=r,a.parentNode.insertBefore(k,a)})
              (window, document, "script", "https://cdn.jsdelivr.net/npm/yandex-metrica-watch/tag.js", "ym");

              ym(95636701, "init", {
                    clickmap:true,
                    trackLinks:true,
                    accurateTrackBounce:true,
                    webvisor:false,
                    ecommerce:"dataLayer"
              });`}
          </Script>
        )}
        {process.env.SERVER === "production" && (
          <div>
            <img
              src="https://mc.yandex.ru/watch/95636701"
              style={{ position: "absolute", left: "-9999px" }}
              alt=""
            />
          </div>
        )}
        {/* ?ref= link takibi — hiçbir şey render etmez. */}
        <AffiliateTracker />
        <div className="tw-flex tw-flex-col tw-min-h-screen">
          <SessionProviderWrapper>
            <GoogleOAuthProvider clientId="173591342442-bjferec6evjg4ggpgec0vdc31shiq5uu.apps.googleusercontent.com">
              <WishlistProvider>
                <Header />
                <main className="tw-grow">{children}</main>
                <Footer />
              </WishlistProvider>
            </GoogleOAuthProvider>
          </SessionProviderWrapper>
        </div>
      </body>

      {process.env.SERVER === "production" && (
        <GoogleAnalytics gaId="G-N7Y1Z4TJNL" />
      )}
    </html>
  );
}